    const filter = $('search').value.toLowerCase(); $('watchlist').innerHTML = quotes.filter(q => (q.symbol + q.name).toLowerCase().includes(filter)).map(q => `<button class="watch ${selected === q.symbol ? 'active' : ''}" data-s="${q.symbol}"><div><strong>${q.symbol}</strong><small>NSE · Equity</small></div><div class="q"><strong>${money(q.price)}</strong><span class="${cls(q.change)}">${pct(q.change)}</span></div></button>`).join('') || '<p style="padding:20px;color:#71808f">No matching stocks.</p>';
