function ohlc(r) { $('ohlc').innerHTML = ['open', 'high', 'low', 'close'].map(k => `<span>${k[0].toUpperCase()} <b>${money(r[k])}</b></span>`).join('') + `<span>Vol <b>${r.volume.toLocaleString('en-IN')}</b></span>`; }
function draw() {
    if (!rows.length) { $('chart').innerHTML = '<text x="460" y="170" text-anchor="middle" fill="#7c8b97">No candles available for this period.</text>'; return; }
    const w = 840, h = 275, left = 14, top = 25, min = Math.min(...rows.map(r => r.low)), max = Math.max(...rows.map(r => r.high)), pad = (max - min) * .12 || 1, lo = min - pad, hi = max + pad, y = p => top + (hi - p) / (hi - lo) * h, x = i => left + (i + .5) * w / rows.length, vmax = Math.max(...rows.map(r => r.volume)) || 1;
    let svg = ''; for (let i = 0; i < 5; i++) { const yy = top + i * h / 4, val = hi - i * (hi - lo) / 4; svg += `<line x1="14" y1="${yy}" x2="855" y2="${yy}" stroke="#eef1f4"/><text x="865" y="${yy + 4}" font-size="11" fill="#8a99a5">${val.toFixed(1)}</text>`; }
    if (type === 'line') { const path = rows.map((r, i) => `${i ? 'L' : 'M'}${x(i)} ${y(r.close)}`).join(' '); svg += `<defs><linearGradient id="fade" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#208b7d" stop-opacity=".15"/><stop offset="1" stop-color="#208b7d" stop-opacity="0"/></linearGradient></defs><path d="${path} L${x(rows.length - 1)} 300 L${x(0)} 300 Z" fill="url(#fade)"/><path d="${path}" stroke="#168b7b" stroke-width="2" fill="none"/>`; }
    rows.forEach((r, i) => { const c = r.close >= r.open ? '#269c8b' : '#dc6f7d', xx = x(i), bw = Math.max(1, w / rows.length * .58); if (type === 'candle') svg += `<line x1="${xx}" y1="${y(r.high)}" x2="${xx}" y2="${y(r.low)}" stroke="${c}"/><rect x="${xx - bw / 2}" y="${Math.min(y(r.open), y(r.close))}" width="${bw}" height="${Math.max(1, Math.abs(y(r.open) - y(r.close)))}" fill="${c}"/>`; const vh = r.volume / vmax * 46; svg += `<rect x="${xx - bw / 2}" y="${360 - vh}" width="${bw}" height="${vh}" fill="${c}" opacity=".3"/>`; });
    for (let i = 0; i < 5; i++) { const n = Math.floor(i * (rows.length - 1) / 4); const date = new Date(rows[n].time * 1000).toLocaleString('en-IN', { timeZone: 'Asia/Kolkata', ...(interval === '1d' ? { day: '2-digit', month: 'short' } : { hour: '2-digit', minute: '2-digit', hour12: false }) }); svg += `<text x="${x(n)}" y="386" text-anchor="middle" font-size="11" fill="#8a99a5">${date}</text>`; }
    svg += '<line id="cross" x1="0" x2="0" y1="25" y2="360" stroke="#8fa5b5" stroke-dasharray="3 3" visibility="hidden"/>'; $('chart').innerHTML = svg; ohlc(rows.at(-1)); $('open').textContent = '₹' + money(rows[0].open); $('high').textContent = '₹' + money(max); $('low').textContent = '₹' + money(min); $('volume').textContent = Intl.NumberFormat('en-IN', { notation: 'compact', maximumFractionDigits: 1 }).format(rows.reduce((s, r) => s + r.volume, 0));
}
async function history() { const id = ++request; historyBusy = true; $('ohlc').textContent = 'Loading candles…'; $('chart').style.opacity = '.45'; try { const data = api ? await get(`/api/candles?symbol=${selected}&interval=${interval}`) : demoCandles(); if (id !== request) return; rows = data; draw(); } catch (e) { if (id === request) { rows = []; draw(); error(e); } } finally { if (id === request) { historyBusy = false; $('chart').style.opacity = '1'; } } }
async function refresh() { if (busy) return; busy = true; try { quotes = api ? await get('/api/quotes') : demoQuotes(); renderQuotes(); $('updated').textContent = (mode === 'live' ? 'Fetched ' : 'Sample refreshed ') + new Date().toLocaleTimeString('en-IN', { hour12: false }); $('error').hidden = true; } catch (e) { error(e); } finally { busy = false; } }
function select(s) { selected = s; renderQuotes(); history(); }
$('search').oninput = renderQuotes; $('intervals').querySelectorAll('button').forEach(b => b.onclick = () => { interval = b.dataset.i; document.querySelectorAll('[data-i]').forEach(x => x.classList.toggle('active', x === b)); history(); });['candle', 'line'].forEach(t => $(t).onclick = () => { type = t; $('candle').classList.toggle('active', t === 'candle'); $('line').classList.toggle('active', t === 'line'); draw(); }); $('setup').onclick = () => $('dialog').showModal(); $('close').onclick = () => $('dialog').close();
$('chart').onpointermove = e => { if (!rows.length) return; const rect = $('chart').getBoundingClientRect(), pos = (e.clientX - rect.left) / rect.width * 920, i = Math.max(0, Math.min(rows.length - 1, Math.floor((pos - 14) / 840 * rows.length))), r = rows[i], cx = 14 + (i + .5) * 840 / rows.length; const cross = $('cross'); if (cross) { cross.setAttribute('x1', cx); cross.setAttribute('x2', cx); cross.setAttribute('visibility', 'visible'); } ohlc(r); $('tooltip').hidden = false; $('tooltip').textContent = new Date(r.time * 1000).toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' }) + ' IST'; }; $('chart').onpointerleave = () => { if ($('cross')) $('cross').setAttribute('visibility', 'hidden'); $('tooltip').hidden = true; if (rows.length) ohlc(rows.at(-1)); };
(async () => { try { const r = await fetch('/api/status'); if (r.ok && r.headers.get('content-type')?.includes('application/json')) { const d = await r.json(); api = true; mode = d.mode; } } catch { } if (mode === 'live') { $('mode').textContent = 'ANGEL ONE'; $('notice').textContent = 'Connected through your Python backend. Prices refresh every 5 seconds; candles every 30 seconds.'; $('chartsource').textContent = 'ANGEL ONE · HISTORICAL'; } await Promise.all([refresh(), history()]); setInterval(refresh, 5000); setInterval(() => { if (!historyBusy) history() }, 30000); })();
